descriptor.templateCss:
.solar-inverter-card {
    width: 100%;
    height: 100%;
    background: #0a0a0a;
    border: 2px solid #5b5b5b;
    color: #f5f5f5;
    font-family: Roboto, Arial, sans-serif;
    display: flex;
    flex-direction: column;
    padding: 4px;
    box-sizing: border-box;
    cursor: pointer;
}
.inv-title {
    background: #1f1f1f;
    color: #fff;
    text-align: center;
    font-weight: 800;
    font-size: 16px;
    letter-spacing: .5px;
    padding: 5px 8px;
    border: 1px solid #696969;
    margin-bottom: 4px;
    text-transform: uppercase;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.inv-grid {
    display: flex;
    flex-direction: column;
    gap: 2px;
    flex: 1;
}
.inv-row {
    display: grid;
    grid-template-columns: 1.25fr 1fr;
    align-items: stretch;
    min-height: 26px;
}
.inv-label {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 3px 5px;
    background: #21489d;
    color: #cddcff;
    border: 1px solid #787878;
    font-weight: 700;
    font-size: 12px;
    text-align: center;
}
.inv-row:nth-child(4) .inv-label,
.inv-row:nth-child(5) .inv-label {
    background: #4a148c;
    color: #f3e5f5;
}
.inv-value {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 3px 6px;
    background: #121212;
    border: 1px solid #787878;
    font-weight: 800;
    font-size: 14px;
    color: #68ff6b;
}
.inv-num {
    flex-grow: 1;
    text-align: right;
    padding-right: 6px;
    line-height: 1;
}
.inv-unit {
    width: 28px;
    text-align: left;
    font-size: 11px;
    color: #b8b8b8;
    font-weight: 700;
}
.inv-row--status .inv-value {
    justify-content: center;
    font-size: 15px;
    color: #fff;
    padding: 3px 5px;
}
.inv-row--status .inv-value.run {
    background: #ff1f14;
}
.inv-row--status .inv-value.warn {
    background: #ffae1a;
}
.inv-row--status .inv-value.stop {
    background: #6f7c90;
}
.inv-row--status .inv-value.fault {
    background: #b00020;
}
.inv-row--status .inv-value.idle {
    background: #607d8b;
}
.inv-detail-btn {
    margin-top: 4px;
    border: 1px solid #4d74da;
    background: #2953c7;
    color: #fff;
    font-weight: 800;
    font-size: 12px;
    padding: 5px 8px;
    cursor: pointer;
    width: 100%;
}
.inv-detail-btn:hover {
    filter: brightness(1.15);
}

